SELECT material_id, material_code, material_name, material_spec, material_type, unit, sum(COALESCE(remaining_qty, required_qty - issued_qty)) as remainingQty, group_concat(distinct batch_no) as batchNos, group_concat(id) as materialReqIds, group_concat(batch_id) as batchIds FROM mis_production_material WHERE 1=1
AND batch_id IN
#{item}
AND id IN
#{item}
AND order_id = #{orderId}
AND (remaining_qty > 0 OR (required_qty - issued_qty) > 0) GROUP BY material_id, material_code, material_name, material_spec, material_type, unit

SELECT * FROM mis_production_material WHERE 1=1 AND (remaining_qty > 0 OR (required_qty - issued_qty) > 0)
AND batch_id IN
#{item}
AND order_id = #{orderId}
ORDER BY material_code, batch_no
